pub(crate) fn bad_file_permissions(checker: &Checker, call: &ast::ExprCall) {
    if !checker.semantic().seen_module(Modules::OS) {
        return;
    }

    if checker
        .semantic()
        .resolve_qualified_name(&call.func)
        .is_some_and(|qualified_name| matches!(qualified_name.segments(), ["os", "chmod"]))
    {
        if let Some(mode_arg) = call.arguments.find_argument_value("mode", 1) {
            let known = KnownBits::from_expr(mode_arg, checker.semantic());

            let dangerous_bits = if is_s103_extended_dangerous_bits_enabled(checker.settings()) {
                DANGEROUS_BITS_PREVIEW
            } else {
                DANGEROUS_BITS_STABLE
            };

            if known.oversized || known.ones & !VALID_BITS != 0 {
                // The mask is out of range or otherwise not a valid Unix permission mask.
                checker.report_diagnostic(
                    BadFilePermissions {
                        reason: Reason::Invalid,
                    },
                    mode_arg.range(),
                );
            } else if known.ones & u64::from(dangerous_bits) != 0 {
                // A statically-known bit that we consider dangerous is set.
                checker.report_diagnostic(
                    BadFilePermissions {
                        reason: Reason::Permissive(known.ones as u16),
                    },
                    mode_arg.range(),
                );
            }
            // Otherwise the expression is entirely unknown (or known to be safe), so there's
            // nothing to report.
        }
    }
}

/// Bits that are considered dangerous in stable mode: `S_IWOTH` (`0o2`) and `S_IXGRP` (`0o10`).
const DANGEROUS_BITS_STABLE: u16 = 0o12;
/// Bits that are considered dangerous in preview mode: the stable bits plus `S_IXOTH` (`0o1`) and
/// `S_IWGRP` (`0o20`).
const DANGEROUS_BITS_PREVIEW: u16 = 0o33;
/// The valid range of Unix permission bits (`0o7777`), i.e. bits `0` through `11`.
const VALID_BITS: u64 = 0o7777;

/// An abstract interpretation of the statically-known bits of a permission mask expression.
///
/// We only track the bits that we can prove are *set*; any bit that we can't reason about is
/// treated as unknown (i.e. not set in [`KnownBits::ones`]).
struct KnownBits {
    /// The bits that are known to be set.
    ones: u64,
    /// Whether the value is known to exceed `u64::MAX`, and thus can't be represented at all.
    oversized: bool,
}

impl KnownBits {
    /// A value about which nothing is known.
    const UNKNOWN: Self = Self {
